SELECT COUNT(*)
FROM LECTURE
WHERE LEC_ID = #{lecId}
  AND LMS_PRF_ID = #{professorLmsPrfId}

SELECT COUNT(*)
FROM LECTURE_UPLOADING u
JOIN LECTURE l ON l.LEC_ID = u.LEC_ID
WHERE u.LEC_UPL_ID = #{uploadId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}


WHERE l.LMS_PRF_ID = #{professorLmsPrfId}

ORDER BY u.LEC_UPL_REG_DATE DESC, u.LEC_UPL_ID DESC
OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

mapper.update:
UPDATE LECTURE_UPLOADING
SET LEC_UPL_TITLE   = #{title},
    LEC_UPL_CONTENT = #{content, jdbcType=CLOB}
WHERE LEC_UPL_ID = #{uploadId}

UPDATE LECTURE_UPLOADING_ATTACHMENT
SET ATT_VAL_STATUS = 'DEL'
WHERE LEC_UPL_ATT_ID = #{attachmentId}
  AND LEC_UPL_ID = #{uploadId}
  AND ATT_VAL_STATUS = 'ACT'
